let errorLog = global.get('error_log') || [];

// Vis de siste 10 feilene, nyeste først
const recent = errorLog.slice(-10).reverse();

msg.payload = recent.map(e => ({
    time: e.timestamp.replace('T', ' ').substring(0, 19),
    type: e.type.toUpperCase(),
    source: e.source,
    status: e.statusCode || 'none',
    message: e.message.substring(0, 60)
}));

return msg;

const errorLog = global.get('error_log') || [];

const json = JSON.stringify(errorLog, null, 2);
const filename = `error_log_${new Date().toISOString().replace(/[:.]/g, '-')}.json`;

msg.payload = {
    content: json,
    filename: filename
};

return msg;
